"// lib/services/audit_service.dart\nimport 'package:cloud_firestore/cloud_firestore.dart';\nimport 'package:firebase_auth/firebase_auth.dart';\n\nclass AuditService {\n  final FirebaseAuth _auth = FirebaseAuth.instance;\n  final FirebaseFirestore _firestore = FirebaseFirestore.instance;\n\n  // Log an admin action (e.g., OTP generation, biometric auth)\n  Future<void> logAdminAction(String adminId, String action) async {\n    await _firestore.collection('AdminAuditLog').add({\n      'adminId': adminId,\n      'action': action,\n      'timestamp': FieldValue.serverTimestamp(),\n    });\n  }\n\n  // Retrieve recent audit entries (placeholder implementation)\n  Future<List<Map<String, dynamic>>> getRecentAudits({int limit = 20}) async {\n    final snapshot = await _firestore\n        .collection('AdminAuditLog')\n        .orderBy('timestamp', descending: true)\n        .limit(limit)\n        .get();\n    return snapshot.docs.map((doc) => doc.data()).toList();\n  }\n}\n"